import React from 'react';
import Slider from 'react-slick'; // Slick Carousel kütüphanesini içeri aktarıyoruz
import { Box, Button } from '@mui/material'; // Material UI bileşenleri
import 'slick-carousel/slick/slick.css'; // Slick Carousel stil dosyasını içeri aktarıyoruz
import 'slick-carousel/slick/slick-theme.css'; // Slick Carousel tema stil dosyasını içeri aktarıyoruz

// Slayt içeriği (buraya slaytlarınızın verilerini ekleyeceksiniz)
const slides = [
  // ... slaytlarınızın verileri (örneğin resimler, linkler vb.)
];

const TechCareerSlider = () => {
  // Slayt ayarları (Slick Carousel için yapılandırma)
  const settings = {
    dots: true, // Slaytların altında dairesel göstergeler gösterir
    infinite: true, // Slaytlar sonsuz döngüde oynar
    speed: 500, // Slayt geçiş hızı (milisaniye cinsinden)
    slidesToScroll: 1, // Her kaydırmada kaç slayt hareket eder
    autoplay: true, // Slaytlar otomatik olarak oynar
    autoplaySpeed: 5000, // Otomatik oynatma aralığı (milisaniye cinsinden)
    arrows: true, // Slaytların yanlarında oklar gösterir
    responsive: [
      {
        breakpoint: 1024, // Tablet (yatay) boyutunda ve üzeri için ayarlar
        settings: {
          slidesToShow: 2, // Tabletlerde yan yana 2 slayt gösterir
        },
      },
      {
        breakpoint: 768, // Tablet (dikey) ve daha küçük ekranlar için ayarlar
        settings: {
          slidesToShow: 1, // Küçük ekranlarda tek bir slayt gösterir
          arrows: false, // Küçük ekranlarda okları gizler
        },
      },
    ],
  };

  return (
    <Box sx={{ backgroundColor: '#F5F9FF', py: 4 }}>
      {/* Slayt bileşenini oluşturur */}
      <Slider {...settings}>
        {/* Slayt verilerini döngüye alarak her bir slaytı oluşturur */}
        {slides.map((slide) => (
          <Box key={slide.id} sx={{ px: 2, textAlign: 'center' }}>
            <Button
              href={slide.link} // Slaytın linkine tıklanabilirlik ekler
              sx={{
                p: 0, // Butonun padding'ini sıfırlar
                display: 'relative', // Butonu blok seviyesinde gösterir
                textDecoration: 'none', // Buton üzerindeki alt çizgiyi kaldırır
                '&:hover': { // Buton üzerine gelindiğinde uygulanacak stil
                  transform: 'scale(1.05)', // Butonun biraz büyümesini sağlar
                  transition: 'transform 0.3s ease', // Geçiş animasyonu ekler
                },
              }}
            >
              <Box
                component="img" // Resim öğesi ekler
                src={slide.image} // Slaytın resmini kaynağından alır
                alt={slide.alt} // Resmin alternatif metnini ekler
                sx={{
                  width: '100%', // Resmin genişliği konteynırın genişliğini kaplar
                  height: 'auto', // Resmin yüksekliği otomatik olarak ayarlanır
                  maxWidth: 'calc(33.33% - 4px)', // Boşluklar için ayarlama (satırda 3 slayt)
                  mx: 'auto', // Resim yatay olarak ortalanır
                  borderRadius: 2, // Resmin köşelerini yuvarlar
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)', // Resme hafif bir gölge ekler
                }}
              />
            </Button>
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default TechCareerSlider; // Bileşeni dışa aktarır
